-- Read-only full membership and prior21-day feature reconstruction. Rank is not batting slot.
with g as(select distinct game_pk,game_date,team from mlb_totals_v11e_projected_lineup_players_2025_v1),h as(select g.game_pk,g.game_date,g.team,l.batter,count(*) starts,avg(l.batting_order) avg_order,max(l.game_date) last_start,min(l.game_date) min_date,array_agg(l.game_pk order by l.game_date,l.game_pk) source_games from g join mlb_ml_xyear_lineup_v1 l on l.season=2025 and l.team=g.team and l.game_date>=g.game_date-21 and l.game_date<g.game_date group by g.game_pk,g.game_date,g.team,l.batter),r as(select *,row_number() over(partition by game_pk,team order by starts desc,last_start desc,avg_order,batter) projected_order from h),s as(select * from r where projected_order<=9) select jsonb_agg(jsonb_build_array(coalesce(t.game_pk,s.game_pk),coalesce(t.game_date,s.game_date),coalesce(t.team,s.team),coalesce(t.batter,s.batter),t.projected_order,s.projected_order,t.starts_21d,s.starts,t.avg_order_21d,s.avg_order,t.last_start_date,s.last_start,s.min_date,s.source_games) order by coalesce(t.game_date,s.game_date),coalesce(t.game_pk,s.game_pk),coalesce(t.team,s.team),coalesce(t.batter,s.batter)) rows from mlb_totals_v11e_projected_lineup_players_2025_v1 t full join s using(game_pk,team,batter)
